module ddr4_tRRD_simple_tRRD (
    input logic clk,
    input logic rst_n,
    input logic act_pulse,
    output logic tRRD_block
);

    parameter int TRRD_CYCLES = 6;
    localparam int COUNTER_WIDTH = $clog2(TRRD_CYCLES + 1);

    logic [COUNTER_WIDTH-1:0] counter;

    localparam logic [COUNTER_WIDTH-1:0] TRRD_CYCLES_L = COUNTER_WIDTH'(TRRD_CYCLES);
    localparam logic [COUNTER_WIDTH-1:0] COUNTER_ZERO_L = COUNTER_WIDTH'(0);
    localparam logic [COUNTER_WIDTH-1:0] COUNTER_ONE_L = COUNTER_WIDTH'(1);

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            counter <= COUNTER_ZERO_L;
        end else if (act_pulse) begin
            counter <= TRRD_CYCLES_L - COUNTER_ONE_L;
        end else if (counter > COUNTER_ZERO_L) begin
            counter <= counter - COUNTER_ONE_L;
        end else begin
            counter <= COUNTER_ZERO_L;
        end
    end

    always_comb begin
        tRRD_block = (counter > COUNTER_ZERO_L);
    end

endmodule

suggested_fixes:
(Optional robustness) In constraints/mc_genus.sdc, wrap clock/reset constraints with existence checks, e.g.:
  if {[sizeof_collection [get_ports -quiet clk]]} {
    create_clock -name clk -period 5.000 [get_ports clk]
    set_clock_uncertainty 0.10 [get_clocks clk]
  }
  if {[sizeof_collection [get_ports -quiet rst_n]]} {
    set_false_path -from [get_ports rst_n]
  }
This prevents silent unconstrained runs when GENUS_TOP changes.

Fix run_genus_mc.tcl define handling by moving initialization before read_hdl and removing the unreachable block after exit. Minimal safe pattern:
  - add near the top (before read_hdl):
      set hdl_defs {}
      if {[info exists ::env(GENUS_DEFINES)] && [string trim $::env(GENUS_DEFINES)] ne ""} {
          set hdl_defs [split [string trim $::env(GENUS_DEFINES)]]
      }
  - then use "if {[llength $hdl_defs] > 0} { ... }" around read_hdl
  - delete the entire block that currently appears after "exit".
This resolves both the undefined-variable runtime failure and the unreachable defines logic.

(Optional) Make SDC more robust to top overrides by checking for the clock port before create_clock, e.g.:
  if {[sizeof_collection [get_ports -quiet clk]]} { create_clock ... }
so that TOP overrides don’t accidentally run unconstrained.

